#include <vector>
#include <numeric>

class Solution {
public:
    int minOperations(std::vector<int>& nums, int target) {
        long long total = 0;
        for (int x : nums) total += x;
        if (total < target) return -1;

        std::vector<int> count(32, 0);
        for (int x : nums) {
            int bit = 0;
            while ((1 << bit) < x) bit++;
            count[bit]++;
        }

        int ops = 0;
        int i = 0;
        while (i < 31) {
            if ((target >> i) & 1) {
                if (count[i] > 0) {
                    count[i]--;
                } else {
                    int j = i;
                    while (j < 31 && count[j] == 0) j++;
                    if (j == 31) return -1;
                    count[j]--;
                    while (j > i) {
                        j--;
                        count[j]++;
                        ops++;
                    }
                }
            }
            count[i + 1] += count[i] / 2;
            i++;
        }
        return ops;
    }
};

